import { ErrorState, Icon, LoadingState } from '../../components/ui.tsx';
import { pl } from '../../i18n/pl.ts';
import { api, apiPaths } from '../../lib/api.ts';
import { useResource } from '../../lib/use-api.ts';
import type { RunScope } from '../run/RunPage.tsx';
import { isTerminal } from '../run/run-model.ts';

/** The report is generated by OŁCyŚ itself and served by its own API; it opens in a new tab. */
export function ReportTab({ scope }: { scope: RunScope }) {
  const { run, version } = scope;
  const done = isTerminal(run.status);
  const path = apiPaths.report(run.id);
  const available = useResource<boolean>(done ? `${path}#head#${version}` : null, () => api.exists(path));
  return (
    <section aria-labelledby="report-title" className="stack">
      <h2 id="report-title">{pl.report.title}</h2>
      <p>{pl.report.intro}</p>
      {!done ? (
        <p className="muted">{pl.report.pending}</p>
      ) : available.error ? (
        <ErrorState title={pl.report.error} error={available.error} onRetry={available.reload} />
      ) : available.data === undefined ? (
        <LoadingState text={pl.report.checking} />
      ) : available.data ? (
        <p>
          <a className="button primary" href={path} target="_blank" rel="noopener noreferrer">
            <Icon name="fact" />
            {pl.report.open}
          </a>
        </p>
      ) : (
        <p className="notice">{pl.report.missing}</p>
      )}
    </section>
  );
}
